package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.setting;

/** The role a user name has on a sheet: clerk (any name without one), steward, or viewer (sees
 *  everything and may change nothing). */
public record Role(String sheetId, String user, String role) {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    public static final String VIEWER = "viewer";
}
package net.officefloor.hq.app.setting;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, n) ->
            new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                ROW, sheetId);
    }

    /** The user's role on the sheet: clerk when none was assigned. */
    public String roleOf(String sheetId, String user) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                ROW, sheetId, user).stream().findFirst().map(Role::role).orElse(Role.CLERK);
    }

    /** Assign (or replace) the user's role on the sheet. */
    public Role set(String sheetId, String user, String role, String by) {
        jdbc.update("DELETE FROM sheet_role WHERE sheet_id = ? AND user_name = ?", sheetId, user);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role, set_by, set_at) "
                + "VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)", sheetId, user, role, by);
        return new Role(sheetId, user, role);
    }
}
package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.List;
import java.util.Map;

/** The permission matrix: for each guarded action, the roles that may take it ({@code perm-<action>},
 *  a comma separated list of roles; blank: the standing rule). Approving and rejecting are not in it:
 *  they stay with stewards. */
public final class Permissions {
    public static final String OPEN = "open";
    public static final String SETTLE = "settle";
    public static final String VOID = "void";
    public static final String REASSIGN = "reassign";
    public static final String CLOSE = "close";
    public static final String REOPEN = "reopen";

    /** The key prefix of an action's entry. */
    public static final String PREFIX = "perm-";

    /** The standing rule: the roles that may take each action while its entry is blank. */
    public static final Map<String, List<String>> STANDING = Map.of(
            OPEN, List.of(Role.CLERK, Role.STEWARD),
            SETTLE, List.of(Role.CLERK, Role.STEWARD),
            VOID, List.of(Role.CLERK, Role.STEWARD),
            CLOSE, List.of(Role.CLERK, Role.STEWARD),
            REASSIGN, List.of(Role.STEWARD),
            REOPEN, List.of(Role.STEWARD));

    private Permissions() {
    }

    /** Whether the key is an action's entry in the matrix. */
    public static boolean isKey(String key) {
        return key.startsWith(PREFIX) && STANDING.containsKey(key.substring(PREFIX.length()));
    }

    /** The roles a stored entry names (blank: none). */
    public static List<String> roles(String value) {
        return value == null || value.isBlank() ? List.of()
                : Arrays.stream(value.split(",")).map(String::trim).toList();
    }

    /** Whether the user's role on the sheet may take the action. */
    public static boolean allows(String sheetId, String user, String action, RoleRepository roles,
            SettingRepository settings) {
        List<String> allowed = roles(settings.find(sheetId, PREFIX + action));
        if (allowed.isEmpty()) allowed = STANDING.get(action);
        return allowed.contains(roles.roleOf(sheetId, user == null ? "" : user));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SetRole {
    public void set(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val RoleRequest request, SheetRepository sheets, RoleRepository roles, Out<Role> role) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        sheets.open(id, user);
        role.set(roles.set(id, request.user(), request.role(), user));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded. */
public class RecordRoleSet {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Role role, Audit audit) {
        audit.record("ROLE_SET sheet=" + role.sheetId() + " by=" + (by == null ? "" : by)
                + " user=" + role.user() + " role=" + role.role());
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class ListRoles {
    public void list(@PathVariable("sheetId") String sheetId, RoleRepository roles,
            ObjectResponse<List<Role>> response) {
        response.send(roles.list(sheetId.trim()));
    }
}
package net.officefloor.hq.app.setting;

import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The first step of every change: a viewer is refused before anything is read or written. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, RoleRepository roles)
            throws ViewerRefusedException {
        if (Role.VIEWER.equals(roles.roleOf(sheetId.trim(), by == null ? "" : by))) {
            throw new ViewerRefusedException("A viewer may change nothing");
        }
    }
}
